"""Hand-crafted edge-case tests comparing against git."""

import os
import shutil
import subprocess
import sys
import tempfile

sys.path.insert(0, "/work/repo")
from snapshot.ignore import ignored_files

GIT = ["git", "-c", "core.ignorecase=false", "-c", "core.excludesFile=" + os.devnull]


def git_ignored(root, home):
    with tempfile.TemporaryDirectory() as tmp:
        repo = os.path.join(tmp, "repo")
        shutil.copytree(root, repo, symlinks=True,
                        ignore=lambda d, names: [".git"] if os.path.samefile(d, root) else [])
        env = {
            "PATH": os.environ.get("PATH", ""),
            "HOME": home,
            "XDG_CONFIG_HOME": home,
            "GIT_CONFIG_NOSYSTEM": "1",
            "GIT_CONFIG_GLOBAL": os.devnull,
        }
        subprocess.run(GIT + ["init", "-q", "--template="], cwd=repo, env=env,
                       check=True, capture_output=True)
        out = subprocess.run(
            GIT + ["ls-files", "-z", "--others", "--ignored", "--exclude-standard"],
            cwd=repo, env=env, check=True, capture_output=True).stdout
    return sorted(p for p in out.decode().split("\0") if p)


def make_tree(root, files):
    for rel, content in files.items():
        p = os.path.join(root, rel)
        os.makedirs(os.path.dirname(p) or root, exist_ok=True)
        with open(p, "w") as f:
            f.write(content if content is not None else "x\n")


CASES = [
    # name, files
    ("negate inside excluded dir", {
        ".gitignore": "foo/\n!foo/keep.txt\n",
        "foo/a.txt": None,
        "foo/keep.txt": None,
    }),
    ("negate inside non-excluded dir", {
        ".gitignore": "foo/*\n!foo/keep.txt\n",
        "foo/a.txt": None,
        "foo/keep.txt": None,
    }),
    ("double star middle", {
        ".gitignore": "a/**/b\n",
        "a/b": None,
        "a/x/b": None,
        "a/x/y/b": None,
        "x/a/b": None,
    }),
    ("double star trailing", {
        ".gitignore": "foo/**\n",
        "foo/a": None,
        "foo/sub/b": None,
    }),
    ("double star leading", {
        ".gitignore": "**/foo\n",
        "foo": None,
        "x/foo": None,
        "x/y/foo": None,
    }),
    ("character class", {
        ".gitignore": "[ab].txt\n",
        "a.txt": None,
        "b.txt": None,
        "c.txt": None,
    }),
    ("character class negated", {
        ".gitignore": "[!ab].txt\n",
        "a.txt": None,
        "b.txt": None,
        "c.txt": None,
    }),
    ("character class range", {
        ".gitignore": "[0-9].log\n",
        "1.log": None,
        "a.log": None,
    }),
    ("trailing spaces", {
        ".gitignore": "foo  \nbar\\ \n",
        "foo": None,
        "foo  ": None,
        "bar ": None,
        "bar": None,
    }),
    ("escaped hash", {
        ".gitignore": "\\#foo\n",
        "#foo": None,
        "foo": None,
    }),
    ("escaped bang", {
        ".gitignore": "*\n\\!foo\n",
        "!foo": None,
        "bar": None,
    }),
    ("blank lines and comments", {
        ".gitignore": "# ignore logs\n\n*.log\n\n# more\n*.tmp\n",
        "a.log": None,
        "b.tmp": None,
        "c.py": None,
    }),
    ("negation does not re-include file in excluded dir", {
        ".gitignore": "node_modules\n!node_modules/keep\n",
        "node_modules/a": None,
        "node_modules/keep": None,
    }),
    ("directory-pattern only matches dirs", {
        ".gitignore": "foo/\n",
        "foo": None,
        "sub/foo/x": None,
    }),
    ("nested gitignore overrides parent", {
        ".gitignore": "*.log\n",
        "sub/.gitignore": "!*.log\n",
        "a.log": None,
        "sub/b.log": None,
        "sub/sub2/c.log": None,
    }),
    ("gitignore in excluded dir ignored", {
        ".gitignore": "sub/\n",
        "sub/.gitignore": "!a\n",
        "sub/a": None,
    }),
    ("empty negation", {
        ".gitignore": "!*.log\n*.log\n",
        "a.log": None,
    }),
    ("star in middle", {
        ".gitignore": "a*b\n",
        "aXb": None,
        "ab": None,
        "a/b": None,
    }),
    ("question mark", {
        ".gitignore": "a?c\n",
        "abc": None,
        "ac": None,
        "a/c": None,
    }),
    ("double slash", {
        ".gitignore": "foo//bar\n",
        "foo/bar": None,
    }),
    ("dot pattern", {
        ".gitignore": ".*\n",
        ".hidden": None,
        "visible": None,
        ".config/x": None,
    }),
    ("leading double star only", {
        ".gitignore": "**\n",
        "foo": None,
        "sub/bar": None,
    }),
    ("subdir reinclude", {
        ".gitignore": "*\n!*/\n!sub/keep\n",
        "a": None,
        "sub/keep": None,
        "sub/other": None,
    }),
    ("deeply nested reinclude", {
        ".gitignore": "*\n!*/\n!.gitignore\n!keep/**\n",
        "a.txt": None,
        "keep/b.txt": None,
        "keep/sub/c.txt": None,
        "other/d.txt": None,
    }),
]


def main():
    fail = 0
    with tempfile.TemporaryDirectory() as home:
        for name, files in CASES:
            with tempfile.TemporaryDirectory() as root:
                make_tree(root, files)
                mine = ignored_files(root)
                theirs = git_ignored(root, home)
                if mine == theirs:
                    print(f"OK   {name}")
                else:
                    fail += 1
                    print(f"FAIL {name}")
                    print(f"  mine:  {mine}")
                    print(f"  git:   {theirs}")
    print(f"\n{fail} failures / {len(CASES)} cases")


if __name__ == "__main__":
    main()

