"""Aggressive random stress test."""

import os
import random
import shutil
import string
import subprocess
import sys
import tempfile

sys.path.insert(0, "/work/repo")
from snapshot.ignore import ignored_files

GIT = ["git", "-c", "core.ignorecase=false", "-c", "core.excludesFile=" + os.devnull]


def git_ignored(root, home):
    with tempfile.TemporaryDirectory() as tmp:
        repo = os.path.join(tmp, "repo")
        shutil.copytree(root, repo, symlinks=True,
                        ignore=lambda d, names: [".git"] if os.path.samefile(d, root) else [])
        env = {
            "PATH": os.environ.get("PATH", ""),
            "HOME": home,
            "XDG_CONFIG_HOME": home,
            "GIT_CONFIG_NOSYSTEM": "1",
            "GIT_CONFIG_GLOBAL": os.devnull,
        }
        subprocess.run(GIT + ["init", "-q", "--template="], cwd=repo, env=env,
                       check=True, capture_output=True)
        out = subprocess.run(
            GIT + ["ls-files", "-z", "--others", "--ignored", "--exclude-standard"],
            cwd=repo, env=env, check=True, capture_output=True).stdout
    return sorted(p for p in out.decode().split("\0") if p)


NAMES = ["foo", "bar", "baz", "src", "sub", "a", "b", "x", "node_modules",
         "build", "dist", "keep", "gen", "pkg"]
EXTS = ["", ".txt", ".log", ".py", ".o", ".tmp", ".md", ".gitignore"]


def gen_name(rng):
    if rng.random() < 0.6:
        return rng.choice(NAMES) + rng.choice(EXTS)
    return "".join(rng.choice(string.ascii_lowercase)
                   for _ in range(rng.randint(1, 4))) + rng.choice(EXTS)


def gen_tree(rng, max_files=30, max_depth=5):
    files = {}
    dirs = {""}

    def add(path, depth):
        if len(files) >= max_files:
            return
        for _ in range(rng.randint(0, 5)):
            if depth < max_depth and rng.random() < 0.4:
                name = rng.choice(NAMES)
                sub = (path + name + "/") if path else name + "/"
                dirs.add(sub.rstrip("/"))
                add(sub, depth + 1)
            else:
                name = gen_name(rng)
                full = (path + name) if path else name
                files[full] = None

    add("", 0)

    # Add .gitignore files in various dirs
    for d in list(dirs) + [""]:
        if rng.random() < 0.5:
            n_lines = rng.randint(0, 8)
            lines = [gen_pattern(rng) for _ in range(n_lines)]
            key = (d + "/.gitignore") if d else ".gitignore"
            files[key] = "\n".join(lines) + "\n"
    return files


PATTERNS = [
    "*.log", "*.txt", "*.py", "foo", "bar", "baz", "build",
    "/foo", "foo/", "/foo/", "/build", "build/",
    "**/foo", "foo/**", "**/foo/**", "foo/*.txt",
    "a/**/b", "**/sub/*.py", "src/**/*.log",
    "!foo", "!*.log", "!build/", "!foo/keep",
    "!**/keep", "!keep.txt",
    "# comment", "", "   ",
    "a?.txt", "[ab]*.log", "[!a]*.py", "[0-9]*.txt",
    "foo\\ bar", "\\!literal", "\\#literal",
    "trailing  ", "trailing\\ ",
    "a*b", "*/foo", "**", "*/", "/*",
    ".*", "**/.*", "src/.*",
    "**/node_modules", "**/node_modules/**",
    "foo/bar/baz", "/a/b/c",
    "foo?", "?oo", "[.]foo",
    "a[.]b", "[^abc]*.log",
    "foo/", "!foo/",
]


def gen_pattern(rng):
    return rng.choice(PATTERNS)


def make_tree(root, files):
    sorted_items = sorted(files.items(), key=lambda kv: -kv[0].count("/"))
    for rel, content in sorted_items:
        p = os.path.join(root, rel)
        d = os.path.dirname(p) or root
        try:
            os.makedirs(d, exist_ok=True)
        except (FileExistsError, NotADirectoryError):
            continue
        if os.path.isdir(p):
            continue
        try:
            with open(p, "w") as f:
                f.write(content if content is not None else "x\n")
        except (IsADirectoryError, FileNotFoundError, NotADirectoryError):
            continue


def main():
    seed = int(sys.argv[1]) if len(sys.argv) > 1 else 0
    rng = random.Random(seed)
    n_iter = int(sys.argv[2]) if len(sys.argv) > 2 else 500

    mismatches = 0
    with tempfile.TemporaryDirectory() as home:
        for i in range(n_iter):
            files = gen_tree(rng)
            if not files:
                continue
            with tempfile.TemporaryDirectory() as root:
                make_tree(root, files)
                try:
                    mine = ignored_files(root)
                    theirs = git_ignored(root, home)
                except Exception as e:
                    print(f"ERROR iter {i}: {e}")
                    continue
                if mine != theirs:
                    mismatches += 1
                    print(f"=== Mismatch #{mismatches} (iter {i}) ===")
                    for k in sorted(files.keys()):
                        if k.endswith(".gitignore"):
                            print(f"  {k}:")
                            for line in (files[k] or "").splitlines():
                                print(f"    | {line!r}")
                        else:
                            print(f"  {k}")
                    only_mine = sorted(set(mine) - set(theirs))
                    only_theirs = sorted(set(theirs) - set(mine))
                    if only_mine:
                        print(f"  Only in mine: {only_mine}")
                    if only_theirs:
                        print(f"  Only in git:  {only_theirs}")
                    if mismatches >= 10:
                        print("Stopping after 10 mismatches")
                        return
    print(f"\n{n_iter} iterations, {mismatches} mismatches")


if __name__ == "__main__":
    main()

